parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.body || item.json;
  if (data.id || data.fingerprint) {
    // Infer country and category defaults
    const phone = data.contact_phone || data.contact_whatsapp || '';
    let country = data.country || 'Algeria';
    if (phone.startsWith('+213') || phone.startsWith('05') || phone.startsWith('06') || phone.startsWith('07')) {
      country = 'Algeria';
    } else if (phone.startsWith('+33')) {
      country = 'France';
    } else if (phone.startsWith('+1')) {
      country = 'USA';
    } else if (phone.startsWith('+44')) {
      country = 'UK';
    } else if (phone.startsWith('+971')) {
      country = 'UAE';
    }

    const isDirectRequest = ['reddit', 'telegram', 'discord'].includes((data.source || '').toLowerCase());
    const lead_category = data.lead_category || (isDirectRequest ? 'ACTIVE_REQUEST' : 'PASSIVE_POTENTIAL');

    results.push({
      json: {
        id: data.id,
        fingerprint: data.fingerprint,
        source: data.source || 'unknown',
        country: country,
        lead_category: lead_category,
        sub_niche: data.sub_niche || data.category_niche || 'General',
        target_market: data.target_market || (country === 'Algeria' ? 'algeria' : 'global'),
        name: data.name || 'Business Owner',
        company_name: data.company_name || data.name || 'Store',
        contact_phone: data.contact_phone || null,
        contact_whatsapp: data.contact_whatsapp || data.contact_phone || null,
        contact_telegram: data.contact_telegram || null,
        contact_instagram: data.contact_instagram || null,
        website_url: data.website_url || null,
        location_wilaya: data.location_wilaya || country,
        category_niche: data.category_niche || 'General B2B',
        raw_content: data.raw_content || '',
        detected_language: data.detected_language || 'fr',
        identified_pain_points: data.identified_pain_points || [],
        proposed_service: data.proposed_service || 'n8n_automation'
      }
    });
  }
}
return results;

